applyAppearance(); render(); if (nativeLibrary) syncLibrary();
configureScanSchedule();

async function importDroppedFiles(files) { const dropped = Array.from(files || []); if (!dropped.length) return; try { if (nativeLibrary?.addDroppedFiles) { await nativeLibrary.addDroppedFiles(dropped); await syncLibrary(); showToast(`${dropped.length} item${dropped.length === 1 ? "" : "s"} added to the library`); return; } state.documents.push(...dropped.filter(file => file.name?.toLowerCase().endsWith(".pdf")).map((file, index) => ({ id: `preview-drop-${Date.now()}-${index}`, title: file.name.replace(/\.[^.]+$/, ""), author: "Local preview", type: "PDF", size: file.size, modified: file.lastModified || Date.now(), pages: 0 }))); state.section = "books"; render(); } catch (error) { showToast(`Could not add dropped item: ${error.message || error}`); } }
document.addEventListener("dragenter", event => { if (event.dataTransfer?.types.includes("Files")) { event.preventDefault(); document.body.classList.add("drag-import-active"); } });
document.addEventListener("dragover", event => { if (event.dataTransfer?.types.includes("Files")) event.preventDefault(); });
document.addEventListener("dragleave", event => { if (!event.relatedTarget) document.body.classList.remove("drag-import-active"); });
document.addEventListener("drop", event => { if (!event.dataTransfer?.files?.length) return; event.preventDefault(); document.body.classList.remove("drag-import-active"); importDroppedFiles(event.dataTransfer.files); });
function hidePdfContextMenu() { document.querySelector("#pdfContextMenu")?.remove(); }
function hideAuthorContextMenu() { document.querySelector("#authorContextMenu")?.remove(); }
function showPdfContextMenu(event, doc) { hidePdfContextMenu(); selectDocumentCard(doc); const menu = document.createElement("div"); menu.id = "pdfContextMenu"; menu.className = "pdf-context-menu"; menu.dataset.document = encodeURIComponent(keyOf(doc)); menu.innerHTML = '<button data-pdf-menu="open">Open PDF</button><button data-pdf-menu="folder">Reveal in folder</button><hr /><button data-pdf-menu="favorite">Toggle favorite</button><button data-pdf-menu="collection">Add to collection</button><button data-pdf-menu="metadata">Edit metadata</button><hr /><button class="danger" data-pdf-menu="trash">Move to trash</button>'; document.body.append(menu); const left = Math.min(event.clientX, window.innerWidth - menu.offsetWidth - 12), top = Math.min(event.clientY, window.innerHeight - menu.offsetHeight - 12); menu.style.left = `${Math.max(12, left)}px`; menu.style.top = `${Math.max(12, top)}px`; }
function showAuthorContextMenu(event, author) { hideAuthorContextMenu(); const menu = document.createElement("div"); menu.id = "authorContextMenu"; menu.className = "pdf-context-menu author-context-menu"; menu.dataset.author = encodeURIComponent(author); menu.innerHTML = `<span class="context-menu-title">${esc(author)}</span><button data-author-menu="rename">Rename author</button><button class="danger" data-author-menu="remove">Remove author</button>`; document.body.append(menu); const left = Math.min(event.clientX, window.innerWidth - menu.offsetWidth - 12), top = Math.min(event.clientY, window.innerHeight - menu.offsetHeight - 12); menu.style.left = `${Math.max(12, left)}px`; menu.style.top = `${Math.max(12, top)}px`; }
async function updateAuthorGroup(author, replacement) { const documents = state.documents.filter(doc => (doc.author || "Unknown author") === author); if (!documents.length) return 0; documents.forEach(doc => { doc.author = replacement; }); render(); if (!nativeLibrary) return documents.length; const updated = await nativeLibrary.updateAuthor({ currentAuthor: author, newAuthor: replacement }); await syncLibrary(); return updated || documents.length; }
grid.addEventListener("contextmenu", event => { const card = event.target.closest("[data-document]"); if (!card) return; const doc = documentById(card.dataset.document); if (!doc) return; event.preventDefault(); showPdfContextMenu(event, doc); });
grid.addEventListener("contextmenu", event => { const card = event.target.closest("[data-author]"); if (!card || state.section !== "authors") return; event.preventDefault(); showAuthorContextMenu(event, card.dataset.author || "Unknown author"); });
document.addEventListener("click", event => { if (!event.target.closest("#pdfContextMenu")) hidePdfContextMenu(); if (!event.target.closest("#authorContextMenu")) hideAuthorContextMenu(); });
document.addEventListener("keydown", event => { if (event.key === "Escape") { hidePdfContextMenu(); hideAuthorContextMenu(); } });
document.addEventListener("click", async event => { const choice = event.target.closest("#pdfContextMenu [data-pdf-menu]"); if (!choice) return; const doc = documentById(choice.closest("#pdfContextMenu").dataset.document), action = choice.dataset.pdfMenu; hidePdfContextMenu(); if (!doc) return; try { if (action === "open") return openDocument(doc); if (action === "folder") return nativeLibrary?.openFolder(doc.path.replace(/[\\/][^\\/]+$/, "")); if (action === "favorite") { setMeta(doc, { favorite: !metaOf(doc).favorite }); return render(); } if (action === "collection") return openCollectionPicker(doc, `Add “${doc.title}” to an existing or new collection.`); if (action === "metadata") { selectDocumentCard(doc); return document.querySelector("#detailEdit").click(); } if (action === "trash") { if (preferences.confirmDestructive && !window.confirm("Move this PDF record to Trash? The original file remains on disk.")) return; if (nativeLibrary) await nativeLibrary.trash(doc.path); else setMeta(doc, { trashed: true }); await syncLibrary(); showToast("Moved to trash"); } } catch (error) { showToast(`Could not complete action: ${error.message || error}`); } });
document.addEventListener("click", async event => { const choice = event.target.closest("#authorContextMenu [data-author-menu]"); if (!choice) return; const menu = choice.closest("#authorContextMenu"), author = decodeURIComponent(menu.dataset.author), action = choice.dataset.authorMenu; hideAuthorContextMenu(); let replacement = author; if (action === "rename") { const proposed = window.prompt(`Rename author “${author}” for every matching PDF:`, author === "Unknown author" ? "" : author); if (proposed === null) return; replacement = proposed.trim(); if (!replacement) return showToast("Enter an author name or choose Remove author."); if (replacement === author) return; } else { if (!window.confirm(`Remove the author from every PDF credited to “${author}”? PDFs will remain in your library.`)) return; replacement = ""; } try { const count = await updateAuthorGroup(author, replacement); showToast(action === "rename" ? `Author renamed for ${count} PDF${count === 1 ? "" : "s"}.` : `Author removed from ${count} PDF${count === 1 ? "" : "s"}.`); } catch (error) { await syncLibrary().catch(() => {}); showToast(`Could not update author: ${error.message || error}`); } });
document.addEventListener("click", event => { const button = event.target.closest("[data-collection-action]"); if (!button || !state.collectionName) return; const action = button.dataset.collectionAction; if (action === "pin") { updateCollectionInfo(state.collectionName, { pinned: !collectionInfo(state.collectionName).pinned }); render(); return; } if (action === "duplicates") { state.collectionDuplicatesOnly = !state.collectionDuplicatesOnly; render(); return; } if (action === "csv" || action === "text") downloadCollectionReport(action); });
